/**
 * @method
 * @name dts_EmpNo_OnFilter
 * @description Emp No On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EmpNo_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "%") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            // alert(dts_EmpNo.NameValue(row, "DEP_CD") );
            if (dts_EmpNo.getCellData(row, "DEP_CD") === scwin.gDepCd ||
                dts_EmpNo.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35602.dts_EmpNo_OnFilter" });
    }
};

/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        let eCnt = 0; // 각 dataset 별 표시 count
        let tIndex = MxTab_1.getSelectedTabIndex();
        // alert(tIndex);
        if (tIndex === 1) {
            eCnt = dts1.getRowCount();
        } else if (tIndex === 2) {
            eCnt = dts2.getRowCount();
        } else if (tIndex === 3) {
            eCnt = dts3.getRowCount();
        }
        $c.stf.fillGridHeaderTotalCnt(eCnt, panel_page);

        // tab을 선택 시 기존 그리드의 '조회결과 없음'표시를 닫는다.
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35602.MxTab_1_OnSelChanged" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        let tIndex = MxTab_1.getSelectedTabIndex();
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF35602.xml", SCREN_PROCS_TP_CD_07);
        // alert(tIndex);
        if (tIndex === 1) {
            $c.data.downloadGridViewExcel(grd_satisfy, {fileName: "주식분산-충족여부 목록", type: "8"});
        } else if (tIndex === 2) {
            $c.data.downloadGridViewExcel(grd_corp_dtl, {fileName: "주식분산-법인별 현황 목록", type: "8"});
        } else if (tIndex === 3) {
            $c.data.downloadGridViewExcel(grd_kn_satisfy, {fileName: "주식분산-종류주식", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35602.btn_Excel_onclick" });
    }
};

