/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_STD_YEAR_1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_STD_YEAR_1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.stf.copyDataSet(dts_STD_YEAR_1, dts_STD_YEAR_2);
    cmb_STD_YEAR_2.setSelectedIndex(0);
    cmb_STD_YEAR_3.setSelectedIndex(0);
    const sbmOptions2 = {
        id : "sbm_dts_DepCd",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts_DepCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_EmpNo",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts_EmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

