    let base_dt = cmb_STD_YEAR_1.getValue();
    let team_cd = $c.cp.valueOfIndex(cmb_dep_cd_1, "VALUE", cmb_dep_cd_1.getSelectedIndex());
    let charge_id = $c.cp.valueOfIndex(cmb_emp_no_1, "VALUE", cmb_emp_no_1.getSelectedIndex());
    let gubun_id = $c.cp.valueOfIndex(cmb_gubun, "CODE", cmb_gubun.getSelectedIndex());
    let dsNm = 'AADD_OUT_SSF';
    let qryId = 'krx.lds.stf.lstmgt.detection.stock_satisfy.list.new';
    let param = '&{P}V_F_MM=' + f_mm;
    param += '&{P}V_BASE_DT=' + base_dt;
    param += '&{P}V_TEAM_CD=' + team_cd;
    param += '&{P}V_CHARGE_ID=' + charge_id;
    param += '&{P}V_SATISFACT_TYP=' + gubun_id;
    $c.bns.fn_SearchBns("ULDSTF35602.xml", dts1, dsNm, qryId, param);
};
